import json, numpy as np
P=json.load(open('/app/output/skeleton_paths.json'))
def rdp(arr,eps=1.5):
 a=np.array(arr,float)
 if len(a)<=2:return [tuple(map(float,a[0])),tuple(map(float,a[-1]))]
 p1,p2=a[0],a[-1];v=p2-p1;den=np.linalg.norm(v)
 if den==0:d=np.linalg.norm(a-p1,axis=1)
 else:d=np.abs(np.cross(v,a-p1)/den)
 i=int(np.argmax(d))
 if d[i]<=eps:return [tuple(a[0]),tuple(a[-1])]
 return rdp(arr[:i+1],eps)[:-1]+rdp(arr[i:],eps)
for e in [0.5,1,1.5,2,3]:print(e,[len(rdp(p,e)) for p in P])
print('coords')
for p in P:
 print([[round(x,1),round(y,1)] for x,y in rdp(p,1.5)])
PY

