from PIL import Image
import numpy as np,json
from scipy.ndimage import distance_transform_edt
src=Image.open('/app/output/main_progress/after_03.png').convert('L')
c=np.array(src.transform((1024,1024),Image.Transform.AFFINE,(.867,0,68.4335,0,.867,68.4335),resample=Image.Resampling.NEAREST))<80
T=np.array(Image.open('/app/target.png').convert('L'))<100;D=distance_transform_edt(~T)
best=(1e9,None)
for dy in range(-22,23):
 for dx in range(-22,23):
  a=np.roll(np.roll(c,dy,0),dx,1); stray=np.sum(a&(D>4.5));
  if stray<best[0]:best=(stray,(dx,dy,np.sum(a&T),np.sum(a),stray/T.sum()))
print('current stray',np.sum(c&(D>4.5))/T.sum(),'best shift stray',best)
# IoU optimal to outer mask using min dist? all target full has inner missing, do best full anyway
bi=(0,None)
for dy in range(-22,23):
 for dx in range(-22,23):
  a=np.roll(np.roll(c,dy,0),dx,1); i=(a&T).sum();u=(a|T).sum();score=i/u
  if score>bi[0]:bi=(score,(dx,dy))
print('iou best full',bi)
